-- Fiche Contraires et synonymes (CM1) - anglais, notion 'en_contraires_synonymes'. Relancer ce script remplace le contenu de la fiche.
insert into contenu_cours (classe, matiere, titre, contenu, statut, notion_id)
select 'cm1', 'english', 'Contraires et synonymes', $fiche$
