[page]
[titre]Grand et petit pour une personne[/titre]
[cadre]Pour la taille d'une personne : grand = [b]tall[/b], petit = [b]short[/b].
Pour un objet : grand = [b]big[/b], petit = [b]small[/b].[/cadre]
[page]
[titre]Je retiens[/titre]
[cadre]Contraire : big ≠ small. Synonyme : big = large.[/cadre]
$fiche$, 'publie', n.id from contenu_notions n where n.code = 'en_contraires_synonymes'
on conflict (notion_id, classe) where statut <> 'archive'
do update set titre = excluded.titre, contenu = excluded.contenu, matiere = excluded.matiere, statut = 'publie', modifie_le = now()
returning id, classe, titre, statut;
